{
  "claims": [
    {
      "claim_text": "To switch a running server from RDB to AOF, enable AOF on the live server with CONFIG SET appendonly yes.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 0 states you need to convert the data by enabling AOF via CONFIG command on the live server first, and passage 1 gives the exact command `redis-cli config set appendonly yes`.",
      "citations": [
        {"index": 0, "quote": "you need to convert the data by enabling AOF via CONFIG command on the live server first."},
        {"index": 1, "quote": "Enable AOF: `redis-cli config set appendonly yes`"}
      ]
    },
    {
      "claim_text": "You must also update redis.conf, otherwise the change is lost when the server restarts.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 1 explicitly says to update redis.conf and warns that if you forget, configuration changes will be lost on restart.",
      "citations": [
        {"index": 1, "quote": "Update your `redis.conf` (potentially through `CONFIG REWRITE`) and ensure that it matches the configuration above. If you forget this step, when you restart the server, the configuration changes will be lost and the server will start again with the old configuration, resulting in a loss of your data."}
      ]
    },
    {
      "claim_text": "Redis automatically blocks incoming writes while it converts the dataset.",
      "verdict": "UNSUPPORTED",
      "reasoning": "No passage states that Redis blocks incoming writes during conversion. Passage 3 instructs the user to stop all writes against the database, implying writes are not automatically blocked.",
      "citations": []
    },
    {
      "claim_text": "Before restarting, wait until aof_rewrite_in_progress and aof_rewrite_scheduled are both 0.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 2 says to wait for AOF rewrite to finish by watching INFO persistence and waiting for aof_rewrite_in_progress and aof_rewrite_scheduled to be 0.",
      "citations": [
        {"index": 2, "quote": "Before restarting the server, wait for AOF rewrite to finish persisting the data. You can do that by watching `INFO persistence`, waiting for `aof_rewrite_in_progress` and `aof_rewrite_scheduled` to be `0`"}
      ]
    },
    {
      "claim_text": "On Redis 7.0 or later, an AOF-only instance can be backed up by copying the files in the directory set by the appendfilename option.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 says since Redis 7.0.0 AOF files reside in a directory determined by the `appenddirname` configuration, not `appendfilename`.",
      "citations": [
        {"index": 4, "quote": "Since Redis 7.0.0, AOF files are split into multiple files which reside in a single directory determined by the `appenddirname` configuration."}
      ]
    },
    {
      "claim_text": "Copying the files while a rewrite is running is safe.",
      "verdict": "CONTRADICTED",
      "reasoning": "Passage 4 states that if copying is done during a rewrite, you might end up with an invalid backup.",
      "citations": [
        {"index": 4, "quote": "However, if this is done during a [rewrite](#log-rewriting), you might end up with an invalid backup."}
      ]
    },
    {
      "claim_text": "To be extra careful you can set auto-aof-rewrite-percentage to 0, which turns off automatic rewrites.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 5 step 1 says to turn off automatic rewrites with CONFIG SET auto-aof-rewrite-percentage 0.",
      "citations": [
        {"index": 5, "quote": "Turn off automatic rewrites with<br/> `CONFIG SET` `auto-aof-rewrite-percentage 0`"}
      ]
    },
    {
      "claim_text": "If you take hard links to those files, you can re-enable rewrites before the copy finishes, because Redis only appends to files in that directory or completely replaces them.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 6 says you may create hard links and then re-enable rewrites after the hard links are created, and explains this works because Redis only appends to files in the directory or completely replaces them.",
      "citations": [
        {"index": 6, "quote": "you may create hard links to the files in `appenddirname` (in step 3 above) and then re-enable rewrites (step 4) after the hard links are created."},
        {"index": 6, "quote": "This works because Redis guarantees that it only appends to files in this directory, or completely replaces them if necessary, so the content should be consistent at any given point in time."}
      ]
    },
    {
      "claim_text": "On Redis 6.0, backing up the AOF is as simple as copying the aof file, and Redis can still load the copy even if it lacks the final part.",
      "verdict": "SUPPORTED",
      "reasoning": "Passage 7 says prior to version 7.0.0 backing up the AOF can be done simply by copying the aof file, and the file may lack the final part but Redis will still be able to load it. Redis 6.0 is prior to 7.0.0.",
      "citations": [
        {"index": 7, "quote": "Prior to version 7.0.0 backing up the AOF file can be done simply by copying the aof file (like backing up the RDB snapshot). The file may lack the final part but Redis will still be able to load it"}
      ]
    }
  ]
}
